'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var exp = require( '@stdlib/math/base/special/exp' );
var pow = require( '@stdlib/math/base/special/pow' );
var erfc = require( '@stdlib/math/base/special/erfc' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );


// MAIN //

/**
* Evaluates the moment-generating function (MGF) for a half-normal distribution with scale parameter `sigma` at a value `t`.
*
* @param {number} t - input value
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} evaluated MGF
*
* @example
* var y = mgf( 0.0, 1.0 );
* // returns 1.0
*
* @example
* var y = mgf( 0.5, 1.0 );
* // returns 1.5670592366928566
*
* @example
* var y = mgf( NaN, 1.0 );
* // returns NaN
*
* @example
* var y = mgf( 0.0, NaN );
* // returns NaN
*
* @example
* var y = mgf( 0.5, -1.0 );
* // returns NaN
*/
function mgf( t, sigma ) {
	var st;
	if (
		isnan( t ) ||
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return NaN;
	}
	if ( sigma === 0.0 ) {
		return ( t === 0.0 ) ? 1.0 : NaN;
	}
	st = sigma * t;

	// MGF = exp(sigma^2 * t^2 / 2) * erfc(-sigma * t / sqrt(2))
	return exp( pow( st, 2.0 ) / 2.0 ) * erfc( -st / SQRT2 );
}


// EXPORTS //

module.exports = mgf;
